import { useState } from 'react';
type AuthForm={fullName?:string;mobile?:string;email:string;password?:string};import { useForm } from 'react-hook-form';import { Section } from '../components/Section';import { Seo } from '../components/Seo';import { api } from '../services/api';export function Dashboard(){const [mode,setMode]=useState<'login'|'register'|'forgot'>('login');const [data,setData]=useState<unknown>();const {register,handleSubmit}=useForm<AuthForm>();async function submit(v:AuthForm){if(mode==='forgot'){await api.post('/auth/forgot-password',v);alert('Reset instructions sent when account exists');return}const res=await api.post(`/auth/${mode}`,v);localStorage.setItem('token',res.data.token);setData((await api.get('/users/dashboard')).data)}return <><Seo title="Customer Dashboard" description="Customer login, profile, loan status, EMI schedule, payments and documents."/><Section><h1 className="text-5xl font-black">Customer Dashboard</h1><div className="mt-8 grid gap-8 lg:grid-cols-3"><form onSubmit={handleSubmit(submit)} className="card space-y-4"><div className="flex gap-2">{(['login','register','forgot'] as const).map(m=><button type="button" className="font-bold text-brand-red" onClick={()=>setMode(m)} key={m}>{m}</button>)}</div>{mode==='register'&&<><input className="input" placeholder="Full Name" {...register('fullName',{required:true})}/><input className="input" placeholder="Mobile" {...register('mobile',{required:true})}/></>}<input className="input" placeholder="Email" {...register('email',{required:true})}/>{mode!=='forgot'&&<input className="input" placeholder="Password" type="password" {...register('password',{required:true})}/>}<button className="btn-primary">Continue</button></form><div className="lg:col-span-2 grid gap-4 md:grid-cols-2">{['Profile','Loan Status','EMI Schedule','Payment History','Documents','Notifications'].map(x=><div className="card" key={x}><h2 className="font-black">{x}</h2><pre className="mt-3 overflow-auto text-xs">{data?JSON.stringify(data,null,2):'Login to view live data'}</pre></div>)}</div></div></Section></>}
